q:
الكود ده بيطبع Excellent وبعدها Invalid لما grade = 90. ليه؟ وإزاي تصلحه؟
if (grade >= 85) print('Excellent');
if (grade >= 75) print('Very good');
else print('Invalid');

hint:
void main() {
  var grade = 90;
  if (grade >= 85) {
    print('Excellent');
  } else if (grade >= 75) {
    print('Very good');
  } else {
    print('Invalid');
  }
}
