void main() {
  var n = 7;
  var isPrime = true;
  if (n <= 1) {
    isPrime = false;
  } else {
    for (var i = 2; i < n; i++) {
      if (n % i == 0) {
        isPrime = false;
        break;
      }
    }
  }
  print('$n prime? $isPrime');
}

